            }
            is AppAction.RequestCopyShare -> {
                buf.putInt(74)
                Unit
            }
            is AppAction.ConfirmCopyShare -> {
                buf.putInt(75)
                FfiConverterString.write(value.`password`, buf)
                Unit
            }
            is AppAction.NavigateToRotateShare -> {
