/**
 * Dashboard tab selection (VAL-SIGNER-*, VAL-PERM-*, VAL-SET-*).
 */

enum class DashboardTab {
    
    SIGNER,
    PERMISSIONS,
    SETTINGS;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeDashboardTab: FfiConverterRustBuffer<DashboardTab> {
    override fun read(buf: ByteBuffer) = try {
        DashboardTab.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: DashboardTab) = 4UL

    override fun write(value: DashboardTab, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * Error kinds surfaced during the load profile flow.
 * These are distinct from OnboardingError since they have different semantics
 * and user-visible messages specific to profile import/recovery.
 * VAL-LOAD-004/010: malformed package; VAL-LOAD-005/011: wrong password;
 * VAL-LOAD-008/017: duplicate; VAL-LOAD-013: no backup; VAL-LOAD-019: unreachable relay.
 */

enum class LoadProfileError {
    
    /**
