public interface AppReconciler {
    
    fun `reconcile`(`update`: AppUpdate)
    
    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceAppReconciler {
    internal object `reconcile`: UniffiCallbackInterfaceAppReconcilerMethod0 {
        override fun callback(`uniffiHandle`: Long,`update`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeAppReconciler.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`reconcile`(
                    FfiConverterTypeAppUpdate.lift(`update`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeAppReconciler.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeAppReconciler.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceAppReconciler.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `reconcile`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_igloo_mobile_core_fn_init_callback_vtable_appreconciler(vtable)
    }
}

